#!/usr/bin/env python3
"""Generate src/checksum/x86/crc32-x86-consts.h.

The x86 CRC32C implementation runs three independent CRC chains over adjacent regions of a large
buffer and merges them. Merging needs the effect of feeding N zero 8-byte words into the CRC
register, which is linear over GF(2) and so can be applied with byte-indexed lookup tables.

This script computes those tables with a plain bit-serial CRC32C (reflected polynomial 0x82F63B78).
It deliberately does not use the CRC32 instruction, so the tables are independent of the code that
consumes them. test/catch2/misc_tests/test_crc32.cpp checks the result against the instruction.

Usage:
    dist/crc32c_shift_tables.py [words-per-stream] > src/checksum/x86/crc32-x86-consts.h
"""
import argparse

POLY = 0x82F63B78
DEFAULT_WORDS = 128


def shift_zero_bits(crc, bits):
    """Feed 'bits' zero bits into a reflected CRC register."""
    for _ in range(bits):
        crc = (crc >> 1) ^ (POLY if crc & 1 else 0)
    return crc


def make_table(words):
    """Return table[byte][value]: the register after 'words' zero words, for a register holding
    'value' in byte position 'byte'. Linearity lets each entry be built from the 32 single-bit
    images."""
    basis = [shift_zero_bits(1 << bit, 64 * words) for bit in range(32)]
    table = [[0] * 256 for _ in range(4)]
    for byte in range(4):
        for value in range(1, 256):
            acc = 0
            for bit in range(8):
                if value >> bit & 1:
                    acc ^= basis[8 * byte + bit]
            table[byte][value] = acc
    return table


def emit_table(name, table):
    lines = ["static const uint32_t %s[4][256] = {" % name]
    for byte in range(4):
        lines.append("  {")
        for i in range(0, 256, 6):
            lines.append("    " + " ".join("0x%08x," % v for v in table[byte][i : i + 6]))
        lines.append("  },")
    lines.append("};")
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("words", nargs="?", type=int, default=DEFAULT_WORDS)
    args = parser.parse_args()
    if args.words <= 0:
        parser.error("words-per-stream must be greater than zero")
    words = args.words
    out = []
    out.append(
        """/*-
 * Public Domain 2014-present MongoDB, Inc.
 * Public Domain 2008-2014 WiredTiger, Inc.
 *
 * This is free and unencumbered software released into the public domain.
 */

#pragma once

#include <inttypes.h>

/*
 * DO NOT EDIT. Generated by dist/crc32c_shift_tables.py %d.
 *
 * WT_CRC32C_STREAM_WORDS is the number of 8-byte words each of the three CRC chains consumes per
 * block. The tables below are only valid for this value, so it is defined next to them.
 *
 * __crc32c_shift_one / __crc32c_shift_two give the CRC register after feeding
 * WT_CRC32C_STREAM_WORDS and 2 * WT_CRC32C_STREAM_WORDS zero words, as one table per register byte:
 * entry [byte][v] is the effect of a register holding v in that byte. Entries are computed with a
 * bit-serial reference CRC, not the CRC32 instruction, and are checked against the instruction by
 * test/catch2/misc_tests/test_crc32.cpp.
 */
#define WT_CRC32C_STREAM_WORDS %d
#define WT_CRC32C_STREAM_BYTES (WT_CRC32C_STREAM_WORDS * sizeof(uint64_t))
#define WT_CRC32C_BLOCK_BYTES (3 * WT_CRC32C_STREAM_BYTES)

// clang-format off"""
        % (words, words)
    )
    out.append(emit_table("__crc32c_shift_one", make_table(words)))
    out.append("")
    out.append(emit_table("__crc32c_shift_two", make_table(2 * words)))
    out.append("// clang-format on")
    print("\n".join(out))


if __name__ == "__main__":
    main()
